/* Pixel-style theme: 4-color palette */
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  padding: 16px;
  background-image: linear-gradient(45deg, #1a1a2e 25%, transparent 25%),
                    linear-gradient(-45deg, #1a1a2e 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #1a1a2e 75%),
                    linear-gradient(-45deg, transparent 75%, #1a1a2e 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  background-color: #0f0f1a;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.6rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 24px;
}

#question {
  font-size: 1.5rem;
  font-weight: bold;
  margin-bottom: 24px;
  min-height: 2em;
  display: flex;
  align-items: center;
  justify-content: center;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

button {
  font-family: var(--font);
  font-size: 1.25rem;
  font-weight: bold;
  padding: 12px 28px;
  min-width: 80px;
  min-height: 52px;
  border: 3px solid var(--text);
  border-radius: 0;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: transform 0.05s, background 0.15s;
  touch-action: manipulation;
}

button:hover:not(:disabled) {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

button:active:not(:disabled) {
  transform: translate(2px, 2px);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.score-line {
  font-size: 1.1rem;
  margin-bottom: 24px;
  color: var(--muted);
}

#score {
  color: var(--accent);
  font-weight: bold;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

#next {
  border-color: var(--accent);
  color: var(--accent);
}

#next:hover:not(:disabled) {
  background: var(--accent);
  color: #fff;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.3rem;
  }
  #question {
    font-size: 1.3rem;
  }
  button {
    padding: 10px 18px;
    font-size: 1.1rem;
    min-width: 70px;
  }
}

const state = {
  step: 0,
  score: 0,
  answered: false,
};

const questions = [
  { text: '2 + 2 = ?', answers: ['4', '5'], correct: 0 },
  { text: '3 + 3 = ?', answers: ['5', '6'], correct: 1 },
];

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

function render() {
  if (state.step < questions.length) {
    const q = questions[state.step];
    questionEl.textContent = q.text;
    answerA.textContent = q.answers[0];
    answerB.textContent = q.answers[1];
    answerA.setAttribute('aria-label', 'Answer A: ' + q.answers[0]);
    answerB.setAttribute('aria-label', 'Answer B: ' + q.answers[1]);
    answerA.disabled = state.answered;
    answerB.disabled = state.answered;
    nextBtn.disabled = !state.answered;
    nextBtn.textContent = 'Next';
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
    nextBtn.textContent = 'Next';
  }
  scoreEl.textContent = String(state.score);
}

function chooseAnswer(index) {
  if (state.answered || state.step >= questions.length) return;
  state.answered = true;
  if (index === questions[state.step].correct) {
    state.score += 1;
  }
  render();
}

answerA.addEventListener('click', () => chooseAnswer(0));
answerB.addEventListener('click', () => chooseAnswer(1));

nextBtn.addEventListener('click', () => {
  if (!state.answered) return;
  state.step += 1;
  state.answered = false;
  render();
});

restartBtn.addEventListener('click', () => {
  state.step = 0;
  state.score = 0;
  state.answered = false;
  render();
});

render();
